**What this code covers**

- Adds JSON serialization capability to any class
- Adds field validation capability
- Returns dict of errors: {field: error_msg}
- Auto-generates __repr__ and __str__
- Subclasses define this dict: {field_name: validation_func}
- Mixin 3: Repr Mixin
- Apply to domain classes
- Real patterns used in Django projects

**Defines:** `JSONSerializableMixin`, `ValidationMixin`, `ReprMixin`, `ClonableMixin`, `TimestampMixin`, `Product`, `User`, `UUIDMixin`, `TimeStampedMixin`, `SoftDeleteMixin`

### ✅ Example 1 — Core Mixin Patterns

```python name=example1_core_mixins.py
# ══════════════════════════════════════════════════
#  ESSENTIAL MIXIN PATTERNS
# ══════════════════════════════════════════════════
import json
import time
import copy
from datetime import datetime

# ─── Mixin 1: Serialization ───
class JSONSerializableMixin:
    """Adds JSON serialization capability to any class"""

    def to_json(self, indent=2) -> str:
        return json.dumps(self.to_dict(), indent=indent, default=str)

    def to_dict(self) -> dict:
        result = {}
        for key, value in self.__dict__.items():
            if not key.startswith('_'):
                if hasattr(value, 'to_dict'):
                    result[key] = value.to_dict()
                elif isinstance(value, list):
                    result[key] = [
                        v.to_dict() if hasattr(v, 'to_dict') else v
                        for v in value
                    ]
                else:
                    result[key] = value
        return result

    @classmethod
    def from_dict(cls, data: dict):
        obj = cls.__new__(cls)
        for key, value in data.items():
            setattr(obj, key, value)
        return obj

    @classmethod
    def from_json(cls, json_str: str):
        return cls.from_dict(json.loads(json_str))

# ─── Mixin 2: Validation ───
class ValidationMixin:
    """Adds field validation capability"""

    # Subclasses define this dict: {field_name: validation_func}
    VALIDATION_RULES: dict = {}

    def validate(self) -> dict:
        """Returns dict of errors: {field: error_msg}"""
        errors = {}
        for field, rule in self.VALIDATION_RULES.items():
            value = getattr(self, field, None)
            try:
                result = rule(value)
                if result is not True and result:
                    errors[field] = result
            except Exception as e:
                errors[field] = str(e)
        return errors

    def is_valid(self) -> bool:
        return len(self.validate()) == 0

    def validate_or_raise(self):
        errors = self.validate()
        if errors:
            raise ValueError(f"Validation failed: {errors}")
        return True

# ─── Mixin 3: Repr Mixin ───
class ReprMixin:
    """Auto-generates __repr__ and __str__"""

    def __repr__(self):
        attrs = ', '.join(
            f"{k}={v!r}"
            for k, v in self.__dict__.items()
            if not k.startswith('_')
        )
        return f"{self.__class__.__name__}({attrs})"

    def __str__(self):
        lines = [f"{self.__class__.__name__}:"]
        for k, v in self.__dict__.items():
            if not k.startswith('_'):
                lines.append(f"  {k}: {v}")
        return "\n".join(lines)

# ─── Mixin 4: Clone/Copy ───
class ClonableMixin:
    """Adds deep copy capability"""

    def clone(self):
        """Returns a deep copy of this object"""
        return copy.deepcopy(self)

    def clone_with(self, **overrides):
        """Clone and override specific fields"""
        cloned = self.clone()
        for key, value in overrides.items():
            if hasattr(cloned, key):
                setattr(cloned, key, value)
            else:
                raise AttributeError(
                    f"'{type(self).__name__}' has no attribute '{key}'"
                )
        return cloned

# ─── Mixin 5: Timestamp ───
class TimestampMixin:
    """Adds created_at and updated_at tracking"""

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.created_at = datetime.now().isoformat()
        self.updated_at = datetime.now().isoformat()

    def touch(self):
        self.updated_at = datetime.now().isoformat()

    @property
    def age_seconds(self):
        created = datetime.fromisoformat(self.created_at)
        return (datetime.now() - created).total_seconds()

# ─── Apply to domain classes ───
class Product(JSONSerializableMixin, ValidationMixin,
              ReprMixin, ClonableMixin, TimestampMixin):

    VALIDATION_RULES = {
        "name"  : lambda v: "Name required" if not v else True,
        "price" : lambda v: "Price must be positive" if v <= 0 else True,
        "stock" : lambda v: "Stock cannot be negative" if v < 0 else True,
    }

    def __init__(self, name, price, stock, category):
        super().__init__()   # TimestampMixin gets called!
        self.name     = name
        self.price    = price
        self.stock    = stock
        self.category = category

class User(JSONSerializableMixin, ValidationMixin,
           ReprMixin, ClonableMixin, TimestampMixin):

    VALIDATION_RULES = {
        "username": lambda v: "Too short" if len(v or '') < 3 else True,
        "email"   : lambda v: "Invalid email" if "@" not in (v or '') else True,
        "age"     : lambda v: "Must be 18+" if (v or 0) < 18 else True,
    }

    def __init__(self, username, email, age, role="user"):
        super().__init__()
        self.username = username
        self.email    = email
        self.age      = age
        self.role     = role

# ─── Testing ALL mixins ───
print("=== Product with all mixins ===")
p = Product("MacBook Pro", 185000, 10, "Electronics")

# ReprMixin
print(repr(p))

# ValidationMixin
print(f"\nIs valid: {p.is_valid()}")
bad_p = Product("", -100, -5, "Bad")
errors = bad_p.validate()
print(f"Errors: {errors}")

# JSONSerializableMixin
print(f"\nJSON:\n{p.to_json()}")

# ClonableMixin
p2 = p.clone_with(price=175000, stock=5)
print(f"\nOriginal: price={p.price}, stock={p.stock}")
print(f"Clone   : price={p2.price}, stock={p2.stock}")

# TimestampMixin
print(f"\nCreated at: {p.created_at}")
time.sleep(0.01)
p.touch()
print(f"Updated at: {p.updated_at}")

print("\n=== User with all mixins ===")
u = User("alice_dev", "alice@test.com", 28, "admin")
print(repr(u))
print(f"\nValid: {u.is_valid()}")
u_json = u.to_json()
u2     = User.from_json(u_json)
print(f"Restored from JSON: {repr(u2)}")
```

### ✅ Example 2 — Django-style Model Mixins

```python name=example2_django_model_mixins.py
# ══════════════════════════════════════════════════
#  DJANGO-STYLE MODEL MIXINS
#  Real patterns used in Django projects
# ══════════════════════════════════════════════════
from datetime import datetime
import uuid

# ─── UUIDMixin ───
class UUIDMixin:
    """Replaces integer PK with UUID"""

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        if not hasattr(self, 'id') or self.id is None:
            self.id = str(uuid.uuid4())

    @property
    def short_id(self):
        return str(self.id)[:8]

# ─── TimeStampedMixin ───
class TimeStampedMixin:
    """created_at + updated_at on every save"""

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.created_at = datetime.now()
        self.updated_at = datetime.now()

    def save(self):
        self.updated_at = datetime.now()
        super().save()
        print(f"  ⏰ Timestamps updated: {self.updated_at.strftime('%H:%M:%S')}")

# ─── SoftDeleteMixin ───
class SoftDeleteMixin:
    """Don't delete — mark as deleted"""

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.is_deleted = False
        self.deleted_at = None

    def delete(self):
        self.is_deleted = True
        self.deleted_at = datetime.now()
        print(f"  🗑️  Soft deleted at {self.deleted_at.strftime('%H:%M:%S')}")

    def restore(self):
        self.is_deleted = False
        self.deleted_at = None
        print(f"  ♻️  Restored!")

    def hard_delete(self):
        print(f"  ❌ HARD DELETE — permanently removed!")

    @classmethod
    def active_only(cls, objects: list) -> list:
        return [o for o in objects if not o.is_deleted]

# ─── AuditMixin ───
class AuditMixin:
    """Track who created/modified + full change log"""

    def __init__(self, *args, created_by=None, **kwargs):
        super().__init__(*args, **kwargs)
        self.created_by  = created_by or "system"
        self.modified_by = None
        self._audit_log  = []

    def save(self, modified_by=None):
        if modified_by:
            self.modified_by = modified_by
            self._audit_log.append({
                "action"    : "MODIFIED",
                "by"        : modified_by,
                "timestamp" : datetime.now().isoformat()
            })
        super().save()

    def get_audit_log(self):
        return self._audit_log.copy()

# ─── SlugMixin ───
class SlugMixin:
    """Auto-generates URL slug from title/name"""
    import re as _re

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._slug = None

    @property
    def slug(self):
        if self._slug:
            return self._slug
        import re
        source = getattr(self, 'title', None) or getattr(self, 'name', '')
        self._slug = re.sub(r'[^a-z0-9]+', '-', source.lower()).strip('-')
        return self._slug

    @slug.setter
    def slug(self, value):
        self._slug = value

# ─── Base "Model" class ───
class Model:
    """Simulated base DB model"""
    def __init__(self, **kwargs):
        pass

    def save(self):
        print(f"  💾 DB: Saving {self.__class__.__name__}")

    def __repr__(self):
        attrs = {k: v for k, v in self.__dict__.items()
                 if not k.startswith('_')}
        return f"{self.__class__.__name__}({attrs})"

# ─── Domain models using mixins ───
class Article(UUIDMixin, TimeStampedMixin, SoftDeleteMixin,
              AuditMixin, SlugMixin, Model):

    def __init__(self, title, content, author, created_by=None):
        super().__init__(created_by=created_by)
        self.title   = title
        self.content = content
        self.author  = author

class UserAccount(UUIDMixin, TimeStampedMixin, SoftDeleteMixin,
                  AuditMixin, Model):

    def __init__(self, username, email, created_by=None):
        super().__init__(created_by=created_by)
        self.username = username
        self.email    = email

# ─── Testing ───
print("=== Article with all model mixins ===")
article = Article(
    title      = "Python OOP Deep Dive",
    content    = "Everything about OOP...",
    author     = "Alice",
    created_by = "admin"
)

print(f"ID       : {article.id}")
print(f"Short ID : {article.short_id}")
print(f"Slug     : {article.slug}")
print(f"Created  : {article.created_at.strftime('%Y-%m-%d %H:%M:%S')}")
print(f"By       : {article.created_by}")
print(f"Deleted  : {article.is_deleted}")

article.save(modified_by="editor")
print(f"Modified by: {article.modified_by}")

article.delete()
print(f"Deleted    : {article.is_deleted}")
article.restore()
print(f"Restored   : {not article.is_deleted}")

print(f"\nAudit log: {article.get_audit_log()}")

# Filter soft-deleted
articles = [
    Article("Post 1", "...", "Alice"),
    Article("Post 2", "...", "Bob"),
    Article("Post 3", "...", "Carol"),
]
articles[1].delete()
active = SoftDeleteMixin.active_only(articles)
print(f"\nAll articles: {len(articles)}")
print(f"Active only : {len(active)}")
```

### ✅ Examples 3, 4, 5 — REST API Mixins, Testing Mixins, Composite Mixin Patterns

```python name=example3_4_5_advanced_mixins.py
# ══════════════════════════════════════════════════
#  ADVANCED MIXIN PATTERNS
#  REST API Mixins + Testing + Composite
# ══════════════════════════════════════════════════

# ─── REST API Mixins (Django REST Framework style) ───
class ListModelMixin:
    """Adds list() to a ViewSet"""
    def list(self, request):
        items = self._get_all()
        return {"status": 200, "count": len(items), "results": items}

class RetrieveModelMixin:
    """Adds retrieve() to a ViewSet"""
    def retrieve(self, request, pk):
        item = self._get_by_id(pk)
        if not item:
            return {"status": 404, "error": "Not found"}
        return {"status": 200, "data": item}

class CreateModelMixin:
    """Adds create() to a ViewSet"""
    def create(self, request):
        data = request.get('data', {})
        item = self._create(data)
        return {"status": 201, "data": item}

class UpdateModelMixin:
    """Adds update() to a ViewSet"""
    def update(self, request, pk):
        data = request.get('data', {})
        item = self._update(pk, data)
        if not item:
            return {"status": 404, "error": "Not found"}
        return {"status": 200, "data": item}

class DestroyModelMixin:
    """Adds destroy() to a ViewSet"""
    def destroy(self, request, pk):
        deleted = self._delete(pk)
        if not deleted:
            return {"status": 404, "error": "Not found"}
        return {"status": 204, "message": "Deleted"}

class BaseViewSet:
    """Base view — provides simulated DB operations"""
    _db = {}
    _counter = 0

    def _get_all(self):
        return list(self._db.values())

    def _get_by_id(self, pk):
        return self._db.get(str(pk))

    def _create(self, data):
        self.__class__._counter += 1
        pk           = str(self._counter)
        data['id']   = pk
        self._db[pk] = data
        return data

    def _update(self, pk, data):
        if str(pk) not in self._db:
            return None
        self._db[str(pk)].update(data)
        return self._db[str(pk)]

    def _delete(self, pk):
        return self._db.pop(str(pk), None) is not None

# ViewSets compose mixins
class ReadOnlyViewSet(ListModelMixin, RetrieveModelMixin, BaseViewSet):
    """Only GET operations"""
    pass

class ModelViewSet(CreateModelMixin, RetrieveModelMixin, UpdateModelMixin,
                   DestroyModelMixin, ListModelMixin, BaseViewSet):
    """Full CRUD"""
    pass

print("=== REST API Mixins ===")
vs = ModelViewSet()
print(vs.create({"data": {"name": "Alice", "email": "alice@test.com"}}))
print(vs.create({"data": {"name": "Bob",   "email": "bob@test.com"}}))
print(vs.list({}))
print(vs.retrieve({}, pk=1))
print(vs.update({"data": {"name": "Alice Smith"}}, pk=1))
print(vs.destroy({}, pk=2))
print(vs.list({}))

# ─── Testing Mixins ───
class AssertionMixin:
    """Adds assertion helpers to test classes"""

    def assert_equal(self, a, b, msg=""):
        assert a == b, f"Expected {a!r} == {b!r}. {msg}"
        print(f"  ✅ PASS: {a!r} == {b!r}")

    def assert_raises(self, exc_type, func, *args):
        try:
            func(*args)
            print(f"  ❌ FAIL: Expected {exc_type.__name__} not raised")
            return False
        except exc_type as e:
            print(f"  ✅ PASS: {exc_type.__name__} raised: {e}")
            return True

    def assert_contains(self, container, item):
        assert item in container, f"{item!r} not in {container!r}"
        print(f"  ✅ PASS: {item!r} in container")

    def assert_truthy(self, value, msg=""):
        assert value, f"Expected truthy, got {value!r}. {msg}"
        print(f"  ✅ PASS: {value!r} is truthy")

class MockMixin:
    """Adds mock object creation"""

    @staticmethod
    def make_mock(**attributes):
        class Mock:
            pass
        mock = Mock()
        for key, value in attributes.items():
            setattr(mock, key, value)
        return mock

    @staticmethod
    def make_request(method="GET", data=None, user=None, path="/"):
        return {
            "method": method,
            "data"  : data or {},
            "user"  : user or {"username": "testuser", "authenticated": True},
            "path"  : path
        }

class SetupTeardownMixin:
    """Adds setUp/tearDown lifecycle"""
    _setup_done    = False
    _teardown_done = False

    def run_test(self, test_func):
        self.setUp()
        try:
            test_func()
            print(f"  ✅ Test passed: {test_func.__name__}")
        except AssertionError as e:
            print(f"  ❌ Test FAILED: {test_func.__name__}: {e}")
        finally:
            self.tearDown()

    def setUp(self):
        self._setup_done = True
        print(f"  🔧 setUp for {self.__class__.__name__}")

    def tearDown(self):
        self._teardown_done = True
        print(f"  🧹 tearDown for {self.__class__.__name__}")

class TestCase(AssertionMixin, MockMixin, SetupTeardownMixin):
    """Full test case base — composes all testing mixins"""
    pass

class ProductServiceTest(TestCase):

    def setUp(self):
        super().setUp()
        self.service = ModelViewSet()

    def test_create_product(self):
        result = self.service.create({"data": {"name": "Laptop", "price": 75000}})
        self.assert_equal(result["status"], 201)
        self.assert_contains(result["data"], "id")

    def test_retrieve_missing(self):
        result = self.service.retrieve({}, pk=999)
        self.assert_equal(result["status"], 404)

print("\n=== Testing Mixins ===")
test = ProductServiceTest()
test.run_test(test.test_create_product)
test.run_test(test.test_retrieve_missing)

# ─── Composite Mixin (Mixin of Mixins) ───
class FullModelMixin(
    JSONSerializableMixin if 'JSONSerializableMixin' in dir() else object,
    ValidationMixin       if 'ValidationMixin'       in dir() else object,
    ReprMixin             if 'ReprMixin'             in dir() else object,
    ClonableMixin         if 'ClonableMixin'         in dir() else object,
):
    """Composite mixin bundling common model behaviours"""
    pass

print("\n=== Composite Mixin ===")
print("FullModelMixin bundles: Serializable + Validation + Repr + Clonable")
print("Apply @FullModelMixin to any class to get all 4 behaviours at once!")
```
